"use strict";(self.webpackChunkchzhshch_blog=self.webpackChunkchzhshch_blog||[]).push([["31796"],{29133(e,t,i){i.r(t),i.d(t,{metadata:()=>r,default:()=>c,frontMatter:()=>a,contentTitle:()=>s,toc:()=>h,assets:()=>l});var r=JSON.parse('{"id":"tianya/copyright","title":"","description":"European history once had such a tedious thing as the droit du seigneur (lord\'s right to the first night). Mozart\'s famous opera The Marriage of Figaro is about precisely this kind of business. Probably owing to their race, Westerners are fond of this sort of thing. Having lost the first-night right, they forcibly concocted something called copyright and intellectual property -- merely a transfer of the same pattern. The psychoanalytic school\'s use of sexual psychology to analyze everything may be somewhat extreme, but in the analogy between copyright/intellectual property and the droit du seigneur, Freud was not entirely talking nonsense.","source":"@site/i18n/en/docusaurus-plugin-content-docs/current/tianya/copyright.md","sourceDirName":"tianya","slug":"/tianya/copyright","permalink":"/en/tianya/copyright","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"id":"copyright","title":"","hide_table_of_contents":true,"sidebar_label":"Like the droit du seigneur, copyright and intellectual property are the West\'s most boring tricks \u2014 they must be abolished"},"sidebar":"tianyaSidebar","previous":{"title":"Feminist Manifesto 4: Male beauty consumption is a historical inevitability \u2014 women, boldly consume men!","permalink":"/en/tianya/femalerightsdeclaration4"},"next":{"title":"In a sense, what the Han people should be most grateful for is the Qing dynasty overthrowing the Ming","permalink":"/en/tianya/qingming"}}'),o=i(74848),n=i(28453);let a={id:"copyright",title:"",hide_table_of_contents:!0,sidebar_label:"Like the droit du seigneur, copyright and intellectual property are the West's most boring tricks \u2014 they must be abolished"},s="Like the Droit du Seigneur, Copyright and Intellectual Property Are the West's Most Tedious Tricks -- They Must Be Abolished",l={},h=[];function u(e){let t={em:"em",h1:"h1",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,o.jsxs)(o.Fragment,{children:[(0,o.jsx)(t.header,{children:(0,o.jsx)(t.h1,{id:"like-the-droit-du-seigneur-copyright-and-intellectual-property-are-the-wests-most-tedious-tricks----they-must-be-abolished",children:"Like the Droit du Seigneur, Copyright and Intellectual Property Are the West's Most Tedious Tricks -- They Must Be Abolished"})}),"\n",(0,o.jsxs)(t.p,{children:["European history once had such a tedious thing as the droit du seigneur (lord's right to the first night). Mozart's famous opera ",(0,o.jsx)(t.em,{children:"The Marriage of Figaro"})," is about precisely this kind of business. Probably owing to their race, Westerners are fond of this sort of thing. Having lost the first-night right, they forcibly concocted something called copyright and intellectual property -- merely a transfer of the same pattern. The psychoanalytic school's use of sexual psychology to analyze everything may be somewhat extreme, but in the analogy between copyright/intellectual property and the droit du seigneur, Freud was not entirely talking nonsense."]}),"\n",(0,o.jsx)(t.p,{children:"From the Freudian psychosexual analysis perspective, copyright and intellectual property are a pattern transfer of the most decadent droit du seigneur ideology from medieval Europe, representing Westerners' particular psychological preferences. From an economic perspective, copyright and intellectual property are equally laughable. If you perform the same economic analysis on the droit du seigneur, you'll see that both come from the same mold."}),"\n",(0,o.jsx)(t.p,{children:"Just as the droit du seigneur had to be and ultimately was abolished, copyright and intellectual property must ultimately be abolished too. After the droit du seigneur was abolished, Europe finally emerged from its feudal cage. After copyright and intellectual property are abolished, all the games of capital will no longer work. In other words, the abolition of copyright and intellectual property has the same historical significance as the abolition of the droit du seigneur."}),"\n",(0,o.jsx)(t.p,{children:"If the abolition of the droit du seigneur symbolized the liberation of an abstract humanity, then the abolition of copyright and intellectual property will represent the true liberation of real human beings. Copyright and intellectual property are the true root of private property in reality. They must be uprooted completely."}),"\n",(0,o.jsx)(t.p,{children:"Standing in reality, we must expose the beautiful lies of copyright and intellectual property, reveal the true bloody history of capital's identity behind them -- a vile ideological swindle under the rule of copyright and intellectual property. And this tedious Western contrivance will ultimately be buried, just like the droit du seigneur."})]})}function c(e={}){let{wrapper:t}={...(0,n.R)(),...e.components};return t?(0,o.jsx)(t,{...e,children:(0,o.jsx)(u,{...e})}):u(e)}},28453(e,t,i){i.d(t,{R:()=>a,x:()=>s});var r=i(96540);let o={},n=r.createContext(o);function a(e){let t=r.useContext(n);return r.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(o):e.components||o:a(e.components),r.createElement(n.Provider,{value:t},e.children)}}}]);